1	"use client";
2	
3	import { useActionState, useState } from "react";
4	import { orderServer } from "@/lib/actions";
5	
6	type Plan = {
7	  id: string;
8	  name: string;
9	  cpuCores: number;
10	  ramMB: number;
11	  diskGB: number;
12	  bandwidthTB: number;
13	  priceCents: number;
14	};
15	type Os = { id: string; name: string };
16	
17	export function OrderForm({
18	  plans,
19	  osTemplates,
20	  isAdmin,
21	  balanceCents,
22	}: {
23	  plans: Plan[];
24	  osTemplates: Os[];
25	  isAdmin: boolean;
26	  balanceCents: number;
27	}) {
28	  const [state, action, pending] = useActionState(orderServer, {});
29	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
30	  const [osId, setOsId] = useState(osTemplates[0]?.id ?? "");
31	  const [free, setFree] = useState(false);
32	  const selected = plans.find((p) => p.id === planId);
33	
34	  return (
35	    <form action={action} className="space-y-6">
36	      {state?.error && (
37	        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
38	          {state.error}
39	        </div>
40	      )}
41	
42	      <div>
43	        <label className="label">Choose a plan</label>
44	        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
45	          {plans.map((p) => (
46	            <button
47	              type="button"
48	              key={p.id}
49	              onClick={() => setPlanId(p.id)}
50	              className={`card cursor-pointer p-4 text-left transition-colors ${
51	                planId === p.id ? "border-brand-400 ring-1 ring-brand-400" : "hover:border-slate-600"
52	              }`}
53	            >
54	              <div className="flex items-baseline justify-between">
55	                <span className="font-semibold">{p.name}</span>
56	                <span className="text-lg font-bold">${(p.priceCents / 100).toFixed(2)}</span>
57	              </div>
58	              <p className="mt-1 text-sm text-slate-400">
59	                {p.cpuCores} vCPU · {p.ramMB / 1024} GB RAM · {p.diskGB} GB NVMe
60	              </p>
61	            </button>
62	          ))}
63	        </div>
64	        <input type="hidden" name="planId" value={planId} />
65	      </div>
66	
67	      <div>
68	        <label className="label">Operating system</label>
69	        <div className="flex flex-wrap gap-3">
70	          {osTemplates.map((os) => (
71	            <button
72	              type="button"
73	              key={os.id}
74	              onClick={() => setOsId(os.id)}
75	              className={`btn-secondary ${osId === os.id ? "!border-brand-400 ring-1 ring-brand-400" : ""}`}
76	            >
77	              {os.name}
78	            </button>
79	          ))}
80	        </div>
81	        <input type="hidden" name="osTemplateId" value={osId} />
82	      </div>
83	
84	      <div className="max-w-sm">
85	        <label className="label">Hostname</label>
86	        <input
87	          className="input"
88	          name="hostname"
89	          placeholder="my-server"
90	          pattern="[a-zA-Z0-9]([a-zA-Z0-9\-]*[a-zA-Z0-9])?"
91	          minLength={3}
92	          maxLength={40}
93	          required
94	        />
95	      </div>
96	
97	      {isAdmin && (
98	        <label className="flex items-center gap-2 text-sm text-brand-300">
99	          <input type="checkbox" name="free" value="1" checked={free} onChange={(e) => setFree(e.target.checked)} />
100	          Deploy free of charge (admin perk — no billing, never expires)
101	        </label>
102	      )}
103	
104	      <div className="card flex items-center justify-between">
105	        <div className="text-sm text-slate-400">
106	          <p>
107	            Due today:{" "}
108	            <span className="font-semibold text-white">
109	              {free ? "$0.00" : selected ? `$${(selected.priceCents / 100).toFixed(2)}` : "—"}
110	            </span>{" "}
111	            · Wallet balance: ${(balanceCents / 100).toFixed(2)}
112	          </p>
113	        </div>
114	        <button className="btn-primary px-6" disabled={pending || !planId || !osId}>
115	          {pending ? "Deploying…" : "Deploy VPS"}
116	        </button>
117	      </div>
118	    </form>
119	  );
120	}
