9	
10	  return (
11	    <div>
12	      <div className="flex justify-end">
13	        <button className={open ? "btn-secondary" : "btn-primary"} onClick={() => setOpen((o) => !o)}>
14	          {open ? "Cancel" : "+ New ticket"}
15	        </button>
16	      </div>
17	      {open && (
18	        <form action={action} className="card mt-4 animate-fade-up space-y-4">
19	          {state?.error && (
20	            <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
21	              {state.error}
22	            </div>
23	          )}
24	          <div className="grid gap-4 sm:grid-cols-[1fr_180px]">
25	            <div>
26	              <label className="label">Subject</label>
27	              <input className="input" name="subject" required minLength={3} maxLength={150} placeholder="Briefly, what's going on?" />
28	            </div>
29	            <div>
30	              <label className="label">Priority</label>
31	              <select className="input" name="priority" defaultValue="NORMAL">
32	                <option value="LOW">Low</option>
33	                <option value="NORMAL">Normal</option>
34	                <option value="HIGH">High</option>
35	                <option value="URGENT">Urgent</option>
36	              </select>
37	            </div>
38	          </div>
39	          <div>
40	            <label className="label">Message</label>
41	            <textarea
42	              className="input min-h-32 resize-y"
43	              name="body"
44	              required
45	              minLength={5}
46	              maxLength={10000}
47	              placeholder="Include the server hostname and any error messages — the more detail, the faster we can help."
48	            />
49	          </div>
50	          <div className="flex justify-end">
51	            <button className="btn-primary px-6" disabled={pending}>
52	              {pending ? "Opening…" : "Open ticket"}
53	            </button>
54	          </div>
55	        </form>
56	      )}
57	    </div>
58	  );
59	}
