61	export function ReplyForm({ ticketId }: { ticketId: string }) {
62	  const [state, action, pending] = useActionState(replyTicket, {});
63	  return (
64	    <form action={action} className="space-y-3">
65	      <input type="hidden" name="ticketId" value={ticketId} />
66	      {state?.error && <p className="text-sm text-red-400">{state.error}</p>}
67	      <textarea
68	        className="input min-h-28 resize-y"
69	        name="body"
70	        required
71	        minLength={2}
72	        maxLength={10000}
73	        placeholder="Write a reply…"
74	      />
75	      <div className="flex justify-end">
76	        <button className="btn-primary px-6" disabled={pending}>
77	          {pending ? "Sending…" : "Send reply"}
78	        </button>
79	      </div>
80	    </form>
81	  );
82	}
83	
84	export function TicketStatusButton({ ticketId, status }: { ticketId: string; status: string }) {
85	  const [pending, start] = useTransition();
86	  const closed = status === "CLOSED";
87	  return (
88	    <button
89	      className={closed ? "btn-secondary" : "btn-danger"}
90	      disabled={pending}
91	      onClick={() => start(() => setTicketStatus(ticketId, closed ? "OPEN" : "CLOSED"))}
92	    >
93	      {pending ? "…" : closed ? "Reopen ticket" : "Close ticket"}
94	    </button>
95	  );
96	}
