1	"use client";
2	
3	import { useMemo, useRef, useState } from "react";
4	import { useActionState, useEffect } from "react";
5	import { payAndDeploy } from "@/lib/actions";
6	import { AppLogo } from "@/components/ui/AppLogo";
7	import { VersionPickerModal, type FamilyGroup } from "@/components/customer/VersionPickerModal";
8	import { VPS_TERMS, vpsTermPriceCents, vpsEffectiveMonthly } from "@/lib/billing-terms";
9	import { walletSplit } from "@/lib/wallet-split";
10	import {
11	  EXTRA_DISK_MAX_ADD_GB,
12	  EXTRA_DISK_MIN_GB,
13	  EXTRA_DISK_ONE_WAY_NOTE,
14	  EXTRA_DISK_STEP_GB,
15	  effectiveDiskGB,
16	  extraDiskCentsAt,
17	} from "@/lib/extra-disk";
18	
19	type Plan = {
20	  id: string; name: string; cpuCores: number; ramMB: number; diskGB: number;
21	  bandwidthTB: number; priceCents: number; storageTier: string;
22	};
23	type Image = {
24	  id: string; slug: string; name: string; category: string; family: string;
25	  version: string; logo: string; minRamMB: number; minDiskGB: number;
26	  licenseRequired: boolean; featured: boolean;
27	};
28	type NodeOpt = { id: string; name: string; publicIp: string };
29	
30	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
31	
32	/** APPLICATION-category images with one of these families are split into the Games tab. */
33	const GAME_FAMILIES = new Set(["minecraft", "valheim", "rust", "palworld", "cs2", "terraria"]);
34	
35	/** Install-step tabs. Games are peeled out of Applications into their own tab. */
36	const TABS = [
37	  { key: "os", label: "Operating Systems", match: (i: Image) => i.category === "PLAIN_OS" },
38	  { key: "panels", label: "Control Panels", match: (i: Image) => i.category === "CONTROL_PANEL" },
39	  { key: "apps", label: "Applications", match: (i: Image) => i.category === "APPLICATION" && !GAME_FAMILIES.has(i.family) },
40	  { key: "games", label: "Games", match: (i: Image) => i.category === "APPLICATION" && GAME_FAMILIES.has(i.family) },
41	] as const;
42	
43	const OS_FAMILY_NAMES: Record<string, string> = {
44	  ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
45	  fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", kali: "Kali Linux", opensuse: "openSUSE",
46	};
47	/** Clean family display name (no version) for the OS family cards. */
48	function osFamilyName(img: Image) {
49	  return OS_FAMILY_NAMES[img.family] ?? img.name.replace(/\s+\d.*$/, "").trim() ?? img.family;
50	}
51	
52	function Stepper({ step, steps }: { step: number; steps: string[] }) {
53	  return (
54	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
55	      {steps.map((s, i) => (
56	        <div key={s} className="flex items-center gap-2">
57	          <span
58	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
59	              i === step ? "border-brand-400 bg-brand-500/20 text-brand-200"
60	                : i < step ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
61	                  : "border-white/10 text-slate-500"
62	            }`}
63	          >
64	            {i < step ? "✓" : i + 1}
65	          </span>
66	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
67	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
68	        </div>
69	      ))}
70	    </div>
71	  );
72	}
73	
74	export function DeployWizard({
75	  plans, images, nodes, sshKeys, isAdmin, balanceCents, dedicatedIpAvailable, dedicatedIpPriceCents,
76	  extraDiskPriceCentsPerGb = 0,
77	  defaultPlanId, defaultTermMonths,
78	  promoPercent = 0, promoLabel,
79	}: {
80	  plans: Plan[]; images: Image[]; nodes: NodeOpt[];
81	  sshKeys: { id: string; name: string }[]; isAdmin: boolean; balanceCents: number;
82	  dedicatedIpAvailable?: boolean; dedicatedIpPriceCents?: number;
83	  /**
84	   * Price per GB per month for extra ROOT DISK (admin setting
85	   * `extra_disk_gb_price_cents`). Priced over the term exactly like the dedicated
86	   * IP add-on, so the maths here matches lib/order.ts orderQuote byte-for-byte.
87	   * 0 hides the upsell entirely.
88	   */
89	  extraDiskPriceCentsPerGb?: number;
90	  /**
91	   * Plan pre-selected on step 1, from the `default_plan_slug` admin setting.
92	   *
93	   * An **id**, not the slug the setting stores: this component's `Plan` type carries no
94	   * slug, so matching here would mean widening the payload or matching on `name`. The
95	   * page resolves slug → id against the very array it passes down, so any id arriving
96	   * here is guaranteed to be in `plans`; a stale slug (plan renamed, or deactivated)
97	   * arrives as `undefined` and the wizard falls back to the first plan rather than
98	   * opening with nothing selected and no price on the Review step.
99	   */
100	  defaultPlanId?: string;
101	  /**
102	   * Billing term pre-selected on the Review step, in MONTHS, from `default_term`.
103	   *
104	   * Guaranteed by `defaultTermMonths()` to be one of `VPS_TERMS`. That guarantee is
105	   * load-bearing: the term buttons below are rendered straight from `VPS_TERMS` and
106	   * highlight on `termMonths === t.months`, so an unlisted value (the old setting's
107	   * "quarterly", say) would render a Review step with no term highlighted while the
108	   * hidden `termMonths` field still posted it — and `vpsTerm()` silently falls back to
109	   * monthly, so the customer would be charged for a term nothing on screen showed.
110	   */
111	  defaultTermMonths?: number;
112	  /** Active intro-promo discount (%) on the FIRST term — matches what payAndDeploy charges. */
113	  promoPercent?: number; promoLabel?: string;
114	}) {
115	  const [state, action, pending] = useActionState(payAndDeploy, {} as { error?: string; checkoutUrl?: string });
116	  // Apply the first-term promo to any regular price, mirroring promoPriceCents()
117	  // in lib/promotions.ts so the wizard's displayed price === the checkout charge.
118	  const hasPromo = promoPercent > 0;
119	  const promoCents = (regular: number) => Math.round(regular * (1 - promoPercent / 100));
120	  // Only redirect to Stripe as the result of an EXPLICIT Deploy submit. The flag is
121	  // armed in the Deploy button's onClick (and the Enter-on-final-step path) and
122	  // consumed here, so a stale `checkoutUrl` in state can never redirect on its own —
123	  // e.g. after a back-button remount (ref starts false) or an unrelated re-render.
124	  const submittedRef = useRef(false);
125	  useEffect(() => {
126	    if (state?.checkoutUrl && submittedRef.current) {
127	      submittedRef.current = false;
128	      window.location.href = state.checkoutUrl;
129	    }
130	  }, [state]);
131	  const multiNode = nodes.length > 1;
132	  const steps = ["Plan", ...(multiNode ? ["Location"] : []), "Install", "Add-ons", "Access", "Review"];
133	  const [step, setStep] = useState(0);
134	
135	  const [planId, setPlanId] = useState(defaultPlanId ?? plans[0]?.id ?? "");
136	  const [nodeId, setNodeId] = useState(nodes[0]?.id ?? "");
137	  const [imageId, setImageId] = useState(images.find((i) => i.category === "PLAIN_OS")?.id ?? images[0]?.id ?? "");
138	  const [tab, setTab] = useState<string>("os");
139	  const [modalFamily, setModalFamily] = useState<string | null>(null);
140	  const [q, setQ] = useState("");
141	  const [addons, setAddons] = useState({ malware: false, backup: false, docker: false });
142	  const [dedicatedIp, setDedicatedIp] = useState(false);
143	  // Extra ROOT DISK bought up front. One-way: this space can never be removed
144	  // later, which the Add-ons card and the Review step both state before payment.
145	  const [extraDiskGB, setExtraDiskGB] = useState(0);
146	  const [hostname, setHostname] = useState("");
147	  const [rootPw, setRootPw] = useState("");
148	  const [pubKey, setPubKey] = useState("");
149	  const [free, setFree] = useState(false);
150	  const [termMonths, setTermMonths] = useState(defaultTermMonths ?? VPS_TERMS[0].months);
151	  // Apply the wallet balance by default whenever there's something to apply.
152	  const [useWallet, setUseWallet] = useState(balanceCents > 0);
153	
154	  const plan = plans.find((p) => p.id === planId);
155	  const image = images.find((i) => i.id === imageId);
156	
157	  const activeTab = TABS.find((t) => t.key === tab) ?? TABS[0];
158	
159	  // Images in the active tab, filtered by search.
160	  const tabImages = useMemo(() => {
161	    const needle = q.trim().toLowerCase();
162	    return images.filter(
163	      (i) => activeTab.match(i) && (needle === "" || (i.name + " " + i.version).toLowerCase().includes(needle)),
164	    );
165	  }, [images, activeTab, q]);
166	
167	  // OS tab: group images into one card per family (each with its versions).
168	  const osFamilies = useMemo<FamilyGroup[]>(() => {
169	    const map = new Map<string, FamilyGroup>();
170	    for (const i of tabImages) {
171	      const g = map.get(i.family) ?? { family: i.family, name: osFamilyName(i), logo: i.logo, versions: [] };
172	      g.versions.push(i);
173	      map.set(i.family, g);
174	    }
175	    for (const g of map.values()) g.versions.sort((a, b) => b.version.localeCompare(a.version, undefined, { numeric: true }));
176	    return [...map.values()];
177	  }, [tabImages]);
178	
179	  const openFamily = (g: FamilyGroup) => {
180	    if (g.versions.length === 1) setImageId(g.versions[0].id);
181	    else setModalFamily(g.family);
182	  };
183	  const modalGroup = modalFamily ? osFamilies.find((g) => g.family === modalFamily) : undefined;
184	
185	  const hostnameValid = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i.test(hostname) && hostname.length >= 3;
186	  const planMeetsImage = !!plan && !!image && plan.ramMB >= image.minRamMB && plan.diskGB >= image.minDiskGB;
187	  const ipMonthly = dedicatedIp ? dedicatedIpPriceCents ?? 0 : 0;
188	  // Extra root disk: per-GB/month × GB, then × the term — priced exactly like the
189	  // dedicated IP (no term discount, no promo), matching lib/order.ts orderQuote.
190	  const extraDiskOffered = (extraDiskPriceCentsPerGb ?? 0) > 0;
191	  const extraDiskMonthly = extraDiskCentsAt(extraDiskGB, extraDiskPriceCentsPerGb ?? 0);
192	  const totalDiskGB = plan ? effectiveDiskGB(plan.diskGB, extraDiskGB) : 0;
193	  // Regular (renewal) plan price for the chosen term, and the promo-discounted
194	  // first-term price actually charged. The dedicated IP is billed at full price.
195	  const regularPlanTerm = plan ? vpsTermPriceCents(plan.priceCents, termMonths) : 0;
196	  const promoPlanTerm = promoCents(regularPlanTerm);
197	  const addonTermCents = (ipMonthly + extraDiskMonthly) * termMonths;
198	  const dueCents = free ? 0 : plan ? promoPlanTerm + addonTermCents : 0;
199	  const regularDueCents = free ? 0 : plan ? regularPlanTerm + addonTermCents : 0;
