624	                  v={<span className="text-base font-semibold">{cardCents > 0 ? money(cardCents) : "$0 card"}</span>}
625	                />
626	              )}
627	              <Row k="Wallet after" v={<span className={balanceCents - walletApplied < 0 ? "text-red-300" : "text-emerald-300"}>{money(balanceCents - walletApplied)}</span>} />
628	            </dl>
629	            {extraDiskGB > 0 && (
630	              <p className="mt-3 rounded-lg border border-amber-500/25 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
631	                {EXTRA_DISK_ONE_WAY_NOTE} Your server will have {totalDiskGB} GB for its whole life,
