635	            {split.clampedForStripeMin && (
636	              <p className="mt-3 text-xs text-amber-300">Card payments have a {money(50)} minimum, so we&apos;ll charge {money(cardCents)} to your card and apply the rest ({money(walletApplied)}) from your wallet.</p>
