638	            {!free && cardCents > 0 && (
639	              <p className="mt-3 text-sm text-slate-400">You&apos;ll pay <span className="text-slate-200">{money(cardCents)}</span> securely by card at checkout{walletApplied > 0 ? <> — with {money(walletApplied)} covered from your wallet</> : null}, and your server deploys the moment payment clears.</p>
640	            )}
641	          </div>
642	        )}
643	
644	        <div className="mt-6 flex items-center justify-between">
645	          <button type="button" className="btn-ghost" disabled={step === 0} onClick={() => setStep((s) => Math.max(0, s - 1))}>← Back</button>
646	          {!isLast ? (
647	            <button type="button" className="btn-primary" disabled={curLabel === "Install" && (!image || !planMeetsImage)} onClick={() => setStep((s) => s + 1)}>Continue →</button>
648	          ) : (
649	            <button
650	              className="btn-primary px-6"
651	              disabled={pending || !canDeploy}
652	              onClick={() => { submittedRef.current = true; }}
653	            >
654	              {pending
655	                ? "Deploying…"
656	                : free
657	                  ? "Deploy free"
658	                  : cardCents > 0
659	                    ? `Deploy — ${money(cardCents)} on card`
660	                    : "Deploy — paid from wallet"}
661	            </button>
662	          )}
663	        </div>
664	      </div>
665	    </form>
666	  );
667	}
668	
669	function Row({ k, v }: { k: string; v: React.ReactNode }) {
670	  return (
671	    <div className="flex items-center justify-between">
672	      <dt className="text-slate-400">{k}</dt>
673	      <dd className="text-right">{v}</dd>
674	    </div>
675	  );
676	}
