13	export default async function DeployPage() {
14	  const user = await requireUser();
15	  // The active intro promo (Summer Sale etc.). payAndDeploy charges the promo
16	  // price on the first term (lib/order.ts), so the wizard must DISPLAY it too —
17	  // otherwise displayed ($8.99) ≠ charged ($6.29). Computed server-side so the
18	  // shown promo matches the one checkout applies.
19	  const promo = currentPromo(new Date());
20	  const [plans, images, sshKeys, nodes, capacity, freeIps, defaultPlanSlug, defaultTerm] =
21	    await Promise.all([
22	      db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
23	      db.osTemplate.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { name: "asc" }] }),
24	      db.sshKey.findMany({ where: { userId: user.id }, select: { id: true, name: true, publicKey: true } }),
25	      db.node.findMany({ where: { enabled: true }, select: { id: true, name: true, publicIp: true } }),
26	      capacitySnapshot(),
27	      db.dedicatedIp.count({ where: { status: "FREE" } }),
28	      // Settings → Provisioning, "Default plan". Stored as a slug; resolved to an id
29	      // below because the wizard selects by id.
30	      getSetting("default_plan_slug", ""),
31	      // Settings → Billing, "Default billing term", in months and pre-validated against
32	      // VPS_TERMS.
33	      defaultTermMonths(),
34	    ]);
35	
36	  // Resolve slug → id HERE, against the same `plans` array handed to the wizard, so the
37	  // pre-selection can only ever name a plan the customer can actually see and buy. A
38	  // slug that no longer resolves (plan renamed, or deactivated since an operator chose
39	  // it) yields `undefined` and the wizard keeps its "first plan by sortOrder" default —
40	  // the panel's promise degrades to the old behaviour instead of pre-selecting nothing.
41	  const defaultPlanId = defaultPlanSlug
42	    ? plans.find((p) => p.slug === defaultPlanSlug)?.id
43	    : undefined;
44	
45	  return (
46	    <div className="space-y-6">
47	      <PageHeader title="Deploy a server" sub="NVMe-backed KVM virtual machines, live in under two minutes." />
48	      {capacity.nearCapacity && (
49	        <div className="rounded-2xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
50	          <span className="font-semibold">Host is filling up.</span> We&apos;re at{" "}
51	          {Math.round(capacity.ramUtilization * 100)}% of committed RAM. Larger plans may be briefly unavailable.
52	        </div>
53	      )}
54	      {plans.length === 0 || images.length === 0 ? (
55	        <EmptyState
56	          title="Deployments are temporarily unavailable"
57	          sub="No active plans or images are configured. Please check back soon or contact support."
58	        />
59	      ) : (
60	        <DeployWizard
61	          plans={plans.map((p) => ({
62	            id: p.id,
63	            name: p.name,
64	            cpuCores: p.cpuCores,
65	            ramMB: p.ramMB,
66	            diskGB: p.diskGB,
67	            bandwidthTB: p.bandwidthTB,
68	            priceCents: p.priceCents,
69	            storageTier: p.storageTier,
70	          }))}
71	          images={images.map((o) => ({
72	            id: o.id,
73	            slug: o.slug,
74	            name: o.name,
75	            category: o.category,
76	            family: o.family,
77	            version: o.version,
78	            logo: o.logo,
79	            minRamMB: o.minRamMB,
80	            minDiskGB: o.minDiskGB,
81	            licenseRequired: o.licenseRequired,
82	            featured: o.featured,
83	          }))}
84	          nodes={nodes}
85	          sshKeys={sshKeys.map((k) => ({ id: k.id, name: k.name }))}
86	          isAdmin={user.role === "ADMIN"}
87	          balanceCents={user.balanceCents}
88	          dedicatedIpAvailable={freeIps > 0}
89	          dedicatedIpPriceCents={await dedicatedIpMonthlyCents()}
90	          extraDiskPriceCentsPerGb={await extraDiskPerGbCents()}
91	          defaultPlanId={defaultPlanId}
92	          defaultTermMonths={defaultTerm}
93	          promoPercent={promo.discountPercent}
94	          promoLabel={promo.label}
95	        />
96	      )}
97	    </div>
98	  );
99	}
