1085	function StoragePanel({
1086	  storage,
1087	  serverId,
1088	  useVolume,
1089	  onUseVolumeChange,
1090	}: {
1091	  storage: {
1092	    state: StorageState;
1093	    /** Effective usable space: root free space, plus the volume IF opted in. */
1094	    avail: number;
1095	    /** Free space on the main (root) filesystem. */
1096	    rootAvail: number;
1097	    /** Volume capacity actually being counted — 0 unless the customer opted in. */
1098	    spare: number;
1099	    /** Capacity of the largest unused volume, whether or not it is being used. */
1100	    spareOffered: number;
1101	    /** How many unused volumes are attached (only the largest can be used). */
1102	    spareCount: number;
1103	    total: number;
1104	    diskTotal: number;
1105	    used: number;
1106	    deficitGB: number;
1107	  };
1108	  serverId: string;
1109	  /** Explicit opt-in to use the volume for Docker storage. Default OFF. */
1110	  useVolume: boolean;
1111	  onUseVolumeChange: (next: boolean) => void;
1112	}) {
1113	  // `rootAvail`/`spare` distinguish the main disk from an unformatted volume the
1114	  // engine can format and use (see TargetInfo.spareDiskBytes). `spareOffered` is
1115	  // what's available if the customer opts in; `spare` is what we actually count.
1116	  const { state, avail, rootAvail, spare, spareOffered, spareCount, total, diskTotal, used, deficitGB } = storage;
1117	
1118	  if (state === "unknown") {
1119	    return (
1120	      <div className="rounded-xl border border-white/10 bg-white/[0.02] p-4">
1121	        <p className="section-label mb-2">Storage</p>
1122	        <p className="text-xs text-slate-400">
1123	          Total to migrate: <span className="font-medium text-slate-200">{fmtSize(total)}</span>. We couldn&apos;t read
1124	          the free space on your new server right now — you can still continue, just make sure it has room for the total
1125	          above.
1126	        </p>
1127	      </div>
1128	    );
1129	  }
1130	
1131	  const tone =
1132	    state === "comfortable"
1133	      ? { border: "border-emerald-500/30", bg: "bg-emerald-500/[0.06]", bar: "bg-emerald-400", text: "text-emerald-300" }
1134	      : state === "tight"
1135	        ? { border: "border-amber-500/30", bg: "bg-amber-500/[0.08]", bar: "bg-amber-400", text: "text-amber-300" }
1136	        : { border: "border-red-500/40", bg: "bg-red-500/[0.08]", bar: "bg-red-400", text: "text-red-300" };
1137	
1138	  const usedPct = diskTotal > 0 ? Math.min(100, (used / diskTotal) * 100) : 0;
1139	  const migPct = diskTotal > 0 ? Math.min(100 - usedPct, (total / diskTotal) * 100) : 0;
1140	
1141	  return (
1142	    <div className={`rounded-xl border ${tone.border} ${tone.bg} p-4`}>
1143	      <div className="mb-2 flex flex-wrap items-baseline justify-between gap-2">
1144	        <p className="section-label">Storage</p>
1145	        <p className={`text-xs font-medium ${tone.text}`}>
1146	          {state === "comfortable" && "Fits comfortably"}
1147	          {state === "tight" && "Tight — this will use most of your free space"}
1148	          {state === "wontfit" && "Won't fit on your server"}
