1150	      </div>
1151	
1152	      <div className="mb-3 flex flex-wrap items-baseline justify-between gap-x-6 gap-y-1 text-sm">
1153	        <span className="text-slate-300">
1154	          Total to migrate: <span className="font-semibold text-white">{fmtSize(total)}</span>
1155	        </span>
1156	        <span className="text-slate-300">
1157	          {spare > 0 ? (
1158	            <>
1159	              Usable space:{" "}
1160	              <span className="font-semibold text-white">{fmtSize(rootAvail + spare)}</span>{" "}
1161	              <span className="text-slate-500">
1162	                — {fmtSize(rootAvail)} on the main disk for your files, {fmtSize(spare)} on your
1163	                volume for Docker
