  const user = await requireUser();
  const parsed = z
    .object({
      name: z.string().min(1).max(60),
      publicKey: z.string().min(20).max(4000).regex(/^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/, "Not a valid OpenSSH public key"),
